components.css:
@font-face{font-family:"ds-Manrope";src:url("/fonts/Manrope.ttf") format("truetype");font-style:normal;font-weight:200 800;font-display:swap;}
.ds-home-scene{position:relative;isolation:isolate;display:flex;align-items:flex-end;min-height:clamp(560px,100svh,1040px);overflow:clip;background:#1d1813 url("/media/ambience/eyewear-poster.webp") 50% 50%/cover no-repeat;color:var(--color-paper,#ffffff);font-family:var(--font-body,"ds-Manrope"),sans-serif;line-height:1.6;}
.ds-home-scene::after{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse 85% 105% at 0% 100%,rgb(14 11 8 / 74%),rgb(14 11 8 / 48%) 45%,rgb(14 11 8 / 0)),linear-gradient(0deg,rgb(14 11 8 / 40%),rgb(14 11 8 / 0) 36%);}
.ds-home-bar{position:absolute;inset:0 0 auto;z-index:20;display:flex;align-items:center;gap:32px;height:78px;max-width:1344px;padding-inline:48px;margin:auto;background:transparent;}
.ds-home-bar::before{content:"";position:absolute;inset:0 0 auto;height:168px;background:linear-gradient(rgb(0 0 0 / 76%),rgb(0 0 0 / 46%) 52%,rgb(0 0 0 / 0));pointer-events:none;z-index:-1;}
.ds-home-brand{display:flex;align-items:center;gap:10px;min-height:44px;color:inherit;text-decoration:none;flex-shrink:0;}.ds-home-logo{width:150px;height:auto;}.ds-home-brand>span{font-size:14px;font-weight:600;line-height:1;border-left:1px solid rgb(255 255 255 / 50%);padding-left:12px;}
.ds-home-links{display:flex;align-items:center;gap:28px;margin-left:auto;font-size:14px;font-weight:600;text-shadow:0 1px 12px rgb(0 0 0 / 45%);}.ds-home-links a{display:flex;align-items:center;min-height:44px;color:inherit;text-decoration:none;white-space:nowrap;}.ds-home-links a:hover{color:var(--color-yellow,#ffda00);}
.ds-home-content{width:100%;max-width:1344px;margin-inline:auto;padding:128px 48px 64px;}.ds-home-heading{position:relative;z-index:1;display:grid;gap:22px;max-width:760px;}.ds-home-heading h1{margin:0;font-size:clamp(3rem,7.2vw,6rem);font-weight:650;line-height:.96;letter-spacing:-.04em;text-wrap:balance;text-shadow:0 2px 28px rgb(0 0 0 / 22%);}.ds-home-intro p{margin:0;max-width:36ch;font-size:18px;font-weight:500;line-height:1.5;text-wrap:pretty;}.ds-home-actions{display:flex;flex-wrap:wrap;align-items:center;gap:4px 32px;margin-top:28px;}
.ds-home-primary,.ds-home-text{display:inline-flex;align-items:center;justify-content:space-between;gap:20px;min-height:52px;padding:14px 22px;border:1px solid transparent;border-radius:var(--radius-control,4px);font-weight:700;font-size:.94rem;line-height:1.35;text-decoration:none;text-underline-offset:5px;transition:background var(--duration-fast,160ms) ease,color var(--duration-fast,160ms) ease;}.ds-home-primary{background:var(--color-yellow,#ffda00);color:var(--color-ink,#171717);}.ds-home-primary:hover{background:var(--color-yellow-hover,#f1c900);}.ds-home-text{color:inherit;background:transparent;border:0;padding:12px 0;min-height:44px;}.ds-home-text:hover{text-decoration:underline;text-decoration-thickness:2px;}.ds-home-actions svg{flex-shrink:0;}.ds-home-scene a:focus-visible{outline:3px solid var(--color-yellow,#ffda00);outline-offset:4px;}
@media(max-width:1100px){.ds-home-bar{padding-inline:32px;gap:20px;}.ds-home-links{gap:20px;}.ds-home-content{padding:120px 32px 56px;}.ds-home-intro p{font-size:17px;}}
@media(min-width:801px) and (max-width:960px){.ds-home-logo{width:132px;}.ds-home-links{gap:16px;}.ds-home-bar{gap:16px;}}
@media(max-width:800px){.ds-home-bar{height:72px;}.ds-home-links{display:none;}.ds-home-scene{min-height:max(560px,94svh);}.ds-home-scene::after{background:linear-gradient(0deg,rgb(14 11 8 / 78%),rgb(14 11 8 / 56%) 34%,rgb(14 11 8 / 0) 72%);}.ds-home-heading h1{font-size:clamp(2.75rem,9vw,4.25rem);}}
@media(max-width:600px){.ds-home-bar{height:68px;padding-inline:20px;gap:16px;}.ds-home-brand{gap:4px;}.ds-home-brand>span{font-size:12px;padding-left:8px;}.ds-home-logo{width:128px;}.ds-home-content{padding:104px 20px 32px;}.ds-home-heading{gap:16px;}.ds-home-heading h1{font-size:clamp(2.5rem,12.4vw,3.375rem);line-height:.98;}.ds-home-intro p{font-size:16px;}.ds-home-actions{flex-direction:column;align-items:flex-start;gap:4px;margin-top:20px;}.ds-home-actions a{font-size:15px;}.ds-home-primary{gap:16px;padding-inline:20px;}}
@media(max-width:370px){.ds-home-bar,.ds-home-content{padding-inline:16px;}.ds-home-logo{width:116px;}}
@media(prefers-reduced-motion:reduce){.ds-home-primary,.ds-home-text{transition-duration:.01ms;}}
